#include "autogenerated.h"
#include "lcd.h"

extern "C" I2C_HandleTypeDef hi2c2;

#define LCD_I2C_ADDR 0x27

void setup() {
    hal_setup();
    lcd_setup(&hi2c2, LCD_I2C_ADDR, LCD_BACKLIGHT_ON | LCD_CURSOR_SHOW | LCD_CURSOR_BLINK);
}

int main() {
    setup();

    lcd_set_cursor(0, 0);
    lcd_print("Hello, world!");

    while (1) {
        // logic     
    }
}